        int n = (int) st.nval;
        int m = nextInt();
        int skipA = nextInt();
        int skipB = nextInt();
        int[] a = new int[n], b = new int[m];
        for (int i = 0; i < n; i++) a[i] = nextInt();
        for (int i = 0; i < m; i++) b[i] = nextInt();
