    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0, head);
        ListNode groupPrev = dummy;
        while (true) {
            ListNode node = groupPrev;
            for (int i = 0; i < k; i++) {
                node = node.next;
                if (node == null) return dummy.next;
            }
            ListNode kth = node, nxt = kth.next;
            ListNode prev = nxt, cur = groupPrev.next;
            while (cur != nxt) {
                ListNode tmp = cur.next;
                cur.next = prev;
                prev = cur;
                cur = tmp;
            }
            ListNode tmp = groupPrev.next;
            groupPrev.next = kth;
            groupPrev = tmp;
        }
    }
}

