        if (node != null) {
            node.val = value;
            remove(node);
            addFront(node);
            return;
        }
        if (cache.size() == cap) {
            Node last = tail.prev;
            remove(last);
            cache.remove(last.key);
        }
        node = new Node(key, value);
        cache.put(key, node);
        addFront(node);
