    static boolean same(TreeNode a, TreeNode b) {
        if (a == null && b == null) return true;
        if (a == null || b == null) return false;
        return a.val == b.val && same(a.left, b.right) && same(a.right, b.left);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        st = new StreamTokenizer(br);
        StringBuilder out = new StringBuilder();
        if (!hasNext()) return;
        int n = (int) st.nval;
        String[] tok = new String[n];
        for (int i = 0; i < n; i++) tok[i] = nextToken();
        TreeNode root = build(tok);
        out.append(same(root, root) ? "true" : "false").append('\n');
        System.out.print(out);
    }
}

