import java.io.*;
import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;

        TreeNode(int v) { val = v; }
    }

    static StreamTokenizer st;

    static boolean hasNext() throws IOException {
        return st.nextToken() != StreamTokenizer.TT_EOF;
    }

    static int nextInt() throws IOException {
        st.nextToken();
        return (int) st.nval;
    }

    static String nextToken() throws IOException {
        st.nextToken();
        if (st.ttype == StreamTokenizer.TT_NUMBER) return String.valueOf((int) st.nval);
        return st.sval;
    }

    static TreeNode build(String[] tok) {
        if (tok.length == 0 || tok[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(tok[0]));
        Deque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tok.length) {
            TreeNode node = q.poll();
            if (i < tok.length && !tok[i].equals("null")) {
                node.left = new TreeNode(Integer.parseInt(tok[i]));
                q.add(node.left);
            }
            i++;
            if (i < tok.length && !tok[i].equals("null")) {
                node.right = new TreeNode(Integer.parseInt(tok[i]));
                q.add(node.right);
            }
            i++;
        }
        return root;
    }

    static int best = 0;

    static int depth(TreeNode node) {
        if (node == null) return 0;
        int left = depth(node.left), right = depth(node.right);
        if (left + right > best) best = left + right;
        return (left > right ? left : right) + 1;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        st = new StreamTokenizer(br);
        StringBuilder out = new StringBuilder();
        if (!hasNext()) return;
        int n = (int) st.nval;
        String[] tok = new String[n];
        for (int i = 0; i < n; i++) tok[i] = nextToken();
        TreeNode root = build(tok);
        depth(root);
        out.append(best).append('\n');
        System.out.print(out);
    }
}
